      "kind": "hook",
      "finding": 0,
      "title": "Can adherence stop the virus?",
      "goal": "Change treatment adherence and see how many people recover at the outbreak's peak.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "no one sticks",
        "highEnd": "everyone sticks"
