        "parameter": "beta3",
        "label": "Transmission by quitters",
        "lowEnd": "hard to catch",
        "highEnd": "very catchy"
      },
      "watch": "quitters",
      "whatIf": {
        "prompt": "What if quitters passed it on twice as easily?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "cQ",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.006
      },
      "effect": "When quitters pass the virus on twice as easily, the quitters peak is higher by more than 0.006.",
      "prediction": {
        "prompt": "Which town has more quitters at the peak?",
        "claimed": "the town where quitters spread twice as easily",
        "other": "this town"
      },
      "passage": {
        "title": "Greatest transmission risk",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Quitters are the most dangerous source of new infections."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "Faster chronic recovery",
      "goal": "Raise the recovery rate for chronic infections and watch the quitters peak fall.",
      "control": {
        "parameter": "rho",
        "label": "Chronic recovery rate",
        "lowEnd": "slow recovery",
        "highEnd": "fast recovery"
