      "watch": "quitters",
      "whatIf": {
        "prompt": "What if chronic recovery were twice as fast?",
        "parameter": "rho",
        "value": 0.106
      },
      "difference": {
        "compartment": "cQ",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "lower",
        "by": 0.001
      },
      "effect": "When chronic recovery doubles, the quitters peak is lower by more than 0.001.",
      "prediction": {
        "prompt": "Which town has fewer quitters at the peak?",
        "claimed": "the town with faster chronic recovery",
        "other": "this town"
      },
      "passage": {
        "title": "Chronic recovery threshold",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that $ℛ_{0}$ falls below 1."
      },
      "carryForward": "Treating chronic infections faster leaves fewer people to spread the virus."
