      "difference": {
        "compartment": "cQ",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.001
      },
      "effect": "When the quitting rate doubles, the quitters peak is higher by more than 0.001.",
      "prediction": {
        "prompt": "Which town has more quitters at the peak?",
        "claimed": "the town that quits twice as often",
        "other": "this town"
      },
      "passage": {
        "title": "Adherence threshold",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "More quitting means more people stuck spreading the virus."
